// ---------------------------------------------------------------- settings
const MAX_ATTEMPTS = 2;        // total researcher passes (1 = no revision loop)
const MIN_CRITIC_SCORE = 75;   // a draft below this never reaches the writer

const f = $input.first().json;
const question = String(f['Research question'] ?? f.question ?? '').trim();

return [{
  json: {
    question,
    audience: f['Who is this for'] || 'the requester',
    deliverable_type: f['Deliverable'] || 'Email brief',
    requester_email: f['Your email for the draft'] || '',
    max_attempts: MAX_ATTEMPTS,
    min_score: MIN_CRITIC_SCORE,
    commissioned_at: new Date().toISOString(),
    attempt: 1,
  },
}];

const brief = $('Prepare Brief').first().json;
const plan = $input.first().json.output ?? $input.first().json;
return [{
  json: {
    ...brief,
    plan,
    subquestions: plan.subquestions ?? [],
    criteria: plan.evaluation_criteria ?? [],
    prior_findings: [],
    gaps: [],
    research_round: 1,
  },
}];

