// The state arrives from two possible places: the first pass (Start Research) or a
// revision pass (Revision Brief). Try the later one first, fall back gracefully.
let state = null;
for (const name of ['Revision Brief', 'Start Research']) {
  try {
    const candidate = $(name).first().json;
    if (candidate && candidate.plan) { state = candidate; break; }
  } catch (e) { /* node did not run in this execution */ }
}
if (!state) throw new Error('Research state missing — check the Start Research node output');

const research = $input.first().json.output ?? $input.first().json;

const prior = state.prior_findings ?? [];
const merged = [...prior, ...(research.claims ?? [])];
// de-duplicate by claim text, keep the newest
const seen = new Set();
const claims = merged.filter(cl => {
  const key = String(cl.claim ?? '').toLowerCase().slice(0, 120);
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [{
  json: {
    ...state,
    research,
    claims,
    claim_count: claims.length,
    sourced_claim_count: claims.filter(cl => cl.url || cl.source).length,
    open_gaps: research.open_gaps ?? [],
    attempt: state.attempt,
  },
}];

