const state = $('Compile Findings').last().json;
const verdict = $input.first().json.output ?? $input.first().json;

const score = Number(verdict.score ?? 0);
const passed = verdict.verdict === 'PASS' || score >= state.min_score;
const canRetry = !passed && state.attempt < state.max_attempts;

return [{
  json: {
    ...state,
    verdict: passed ? 'PASS' : 'REVISE',
    raw_verdict: verdict.verdict,
    score,
    passed,
    can_retry: canRetry,
    criteria_met: verdict.criteria_met ?? [],
    criteria_unmet: verdict.criteria_unmet ?? [],
    unsupported_claims: verdict.unsupported_claims ?? [],
    required_fixes: verdict.required_fixes ?? [],
    notes_for_writer: verdict.notes_for_writer ?? '',
  },
}];

const s = $input.first().json;
return [{
  json: {
    ...s,
    attempt: s.attempt + 1,
    research_round: s.attempt + 1,
    prior_findings: s.claims ?? [],
    gaps: [...(s.required_fixes ?? []), ...(s.criteria_unmet ?? []), ...(s.unsupported_claims ?? [])],
  },
}];

