const s = $('Route Decision').first().json;
const d = $input.first().json.output ?? $input.first().json;

const sources = (d.sources ?? []).map(x => `- ${x.name}${x.published ? ` (${x.published})` : ''}${x.url ? ` — ${x.url}` : ''}`).join('\n') || '- none cited';
const sections = (d.sections ?? []).map(sec => `## ${sec.heading}\n${sec.body}`).join('\n\n');
const caveats = (d.caveats ?? []).map(x => `- ${x}`).join('\n') || '- none';
const next = (d.next_steps ?? []).map(x => `- ${x}`).join('\n') || '- none';

const markdown = `# ${d.title}

${d.direct_answer}

${sections}

## Caveats
${caveats}

## Sources
${sources}

## Next steps
${next}

---
_QA: ${s.verdict} at ${s.score}/100 after ${s.attempt} research round(s). Unverified items are excluded by design._
`;

return [{
  json: {
    ...s,
    title: d.title,
    direct_answer: d.direct_answer,
    deliverable_markdown: markdown,
    sources: sources,
    source_count: (d.sources ?? []).length,
    requester_email: s.requester_email || '',
    completed_at: new Date().toISOString(),
    slack_summary: `*${d.title}*\n${d.direct_answer}\n_QA ${s.verdict} · ${s.score}/100 · ${s.attempt} round(s) · ${(d.sources ?? []).length} sources_`,
  },
}];
